namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department? Department { get; set; }
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [StringLength(20, ErrorMessage = "Student ID cannot exceed 20 characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, methods, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed 9:00–10:30 AM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs, along with algorithm analysis.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:30 PM", DepartmentId = 1, InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has published over 30 research papers.", IsFeatured = true },
            new() { Id = 3, Title = "Web Development", Description = "Full-stack web development covering HTML, CSS, JavaScript, and server-side frameworks.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–2:00 PM", DepartmentId = 1, InstructorName = "Prof. Carol Williams", InstructorBio = "Prof. Williams is a former industry developer with expertise in modern web technologies.", IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", Description = "Introduction to differential and integral calculus. Covers limits, derivatives, and basic integration.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–11:00 AM", DepartmentId = 2, InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Description = "Study of vectors, matrices, linear transformations, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 2:00–3:30 PM", DepartmentId = 2, InstructorName = "Dr. Elena Popov", InstructorBio = "Dr. Popov's research focuses on applied linear algebra in machine learning.", IsFeatured = false },
            new() { Id = 6, Title = "Discrete Mathematics", Description = "Logic, set theory, combinatorics, graph theory, and mathematical reasoning for computer science.", Credits = 3, Schedule = "Mon/Wed 3:00–4:30 PM", DepartmentId = 2, InstructorName = "Dr. Frank Johnson", InstructorBio = "Dr. Johnson bridges mathematics and computer science with 20 years of teaching experience.", IsFeatured = false },
            new() { Id = 7, Title = "Classical Mechanics", Description = "Newtonian mechanics, energy, momentum, rotational motion, and oscillations.", Credits = 4, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 3, InstructorName = "Dr. Grace Liu", InstructorBio = "Dr. Liu is a renowned physicist with contributions to experimental mechanics.", IsFeatured = true },
            new() { Id = 8, Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed 11:00 AM–12:30 PM", DepartmentId = 3, InstructorName = "Dr. Henry Okafor", InstructorBio = "Dr. Okafor has conducted groundbreaking research in electromagnetic theory.", IsFeatured = false },
            new() { Id = 9, Title = "Quantum Physics", Description = "Introduction to quantum mechanics, wave-particle duality, and the Schrödinger equation.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", DepartmentId = 3, InstructorName = "Dr. Irene Santos", InstructorBio = "Dr. Santos is a quantum physicist who has worked at CERN and specializes in particle physics.", IsFeatured = false },
            new() { Id = 10, Title = "Database Systems", Description = "Relational databases, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 1, InstructorName = "Prof. James Wright", InstructorBio = "Prof. Wright has extensive industry experience designing large-scale database systems.", IsFeatured = false }
        };

        // Link departments to courses
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
        return true;
    }
}

